function buildAll() {
  const parts = [];
  let chunk = [];
  for (let c = 0; c < 0x110000; c++) {
    if (c >= 0xD800 && c <= 0xDFFF) continue;
    chunk.push(c);
    if (chunk.length === 4096) { parts.push(String.fromCodePoint.apply(null, chunk)); chunk = []; }
  }
  if (chunk.length) parts.push(String.fromCodePoint.apply(null, chunk));
  return parts.join("");
}
function rangesOf(all, expr, flags) {
  const re = new RegExp(expr + "+", "g" + (flags || "u"));
  const out = [];
  let m;
  while ((m = re.exec(all)) !== null) {
    const s = m[0];
    const first = s.codePointAt(0);
    const lastCp = s.codePointAt(s.length - 1);
    // last code point: if last unit is a low surrogate, take pair
    let last;
    const lu = s.charCodeAt(s.length - 1);
    if (lu >= 0xDC00 && lu <= 0xDFFF && s.length >= 2) last = s.codePointAt(s.length - 2); else last = lu;
    out.push([first, last]);
  }
  // surrogates individually
  const single = new RegExp("^" + expr + "$", flags || "u");
  let sStart = -1;
  const sur = [];
  for (let c = 0xD800; c <= 0xDFFF; c++) {
    if (single.test(String.fromCharCode(c))) { if (sStart < 0) sStart = c; }
    else if (sStart >= 0) { sur.push([sStart, c - 1]); sStart = -1; }
  }
  if (sStart >= 0) sur.push([sStart, 0xDFFF]);
  // merge surrogate ranges into out (sorted)
  const all2 = out.concat(sur).sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const r of all2) {
    if (merged.length && merged[merged.length - 1][1] + 1 >= r[0]) merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], r[1]);
    else merged.push([r[0], r[1]]);
  }
  return merged;
}
EOF
