//! Unicode utilities for the lumen runtime (std only).
//!
//! The data reproduces what the original runtime implements, which is Unicode 17.0:
//! property tables (General_Category, Script, Script_Extensions, the 53 ECMAScript binary
//! properties, properties of strings), case folding classes and normalization data were probed
//! from the original and cross-checked against UCD 15.0 (python `unicodedata`, perl, and the
//! `regenerate-unicode-properties` package); full case mappings come from Rust std (Unicode 17.0),
//! which matches the original's `toUpperCase`/`toLowerCase` exactly for every code point.
//! The compact tables live in `tables.rs` (generated by `/tmp/unicode_dev/gen/gen_tables.py`).
//!
//! Quirks of the original reproduced here:
//! * `\p{Basic_Emoji}` contains the 26 regional indicators U+1F1E6..U+1F1FF as single code points,
//!   while `\p{RGI_Emoji}` does not.
//! * `WSpace` is not accepted as an alias of `White_Space` (only `space` is, per ECMA-262);
//!   `Katakana_Or_Hiragana`/`Hrkt` are not accepted script values; names are case-sensitive.
//! * Canonical combining classes are those of UCD 15.0 plus only twelve new non-zero classes
//!   (U+0897, U+10D69..U+10D6D, U+113CE..U+113D0, U+1612F, U+1E5EE, U+1E5EF); other marks added
//!   in Unicode 16.0/17.0 behave as ccc=0 in `normalize`.
//! * Final sigma uses the ICU rule: case-ignorable characters are skipped even when they are
//!   also cased, lone surrogates stop the scan.
//! * `normalize` passes lone surrogates through unchanged and treats them as starters (ccc 0)
//!   that never compose.
#![allow(dead_code)]

mod tables;

use std::sync::OnceLock;

// ---------------------------------------------------------------------------
// Compact table decoding
// ---------------------------------------------------------------------------

/// Reader for the base-64 varint encoding used by `tables.rs`: each byte in 0x30..=0x6F holds
/// five data bits (least significant group first); bit 5 means "more bytes follow".
struct Reader<'a> {
    s: &'a [u8],
    i: usize,
}

impl<'a> Reader<'a> {
    fn new(s: &'a str) -> Self {
        Reader { s: s.as_bytes(), i: 0 }
    }
    fn done(&self) -> bool {
        self.i >= self.s.len()
    }
    fn uv(&mut self) -> u32 {
        let mut v: u32 = 0;
        let mut shift = 0;
        loop {
            let b = (self.s[self.i] - 0x30) as u32;
            self.i += 1;
            v |= (b & 31) << shift;
            if b & 32 == 0 {
                return v;
            }
            shift += 5;
        }
    }
    fn sv(&mut self) -> i64 {
        let u = self.uv() as i64;
        if u & 1 == 0 {
            u >> 1
        } else {
            -((u + 1) >> 1)
        }
    }
}

fn decode_ranges(s: &str) -> Vec<(u32, u32)> {
    let mut r = Reader::new(s);
    let mut out = Vec::new();
    let mut next: u32 = 0;
    while !r.done() {
        let start = next + r.uv();
        let end = start + r.uv();
        out.push((start, end));
        next = end + 1;
    }
    out
}

fn in_ranges(ranges: &[(u32, u32)], c: u32) -> bool {
    // binary search for the last range with start <= c
    let idx = ranges.partition_point(|&(s, _)| s <= c);
    idx > 0 && c <= ranges[idx - 1].1
}

/// Sort and merge (overlapping or adjacent) ranges.
fn normalize_ranges(mut v: Vec<(u32, u32)>) -> Vec<(u32, u32)> {
    v.sort_unstable();
    let mut out: Vec<(u32, u32)> = Vec::with_capacity(v.len());
    for (a, b) in v {
        if let Some(last) = out.last_mut() {
            if a <= last.1.saturating_add(1) {
                if b > last.1 {
                    last.1 = b;
                }
                continue;
            }
        }
        out.push((a, b));
    }
    out
}

/// `a` minus `b` (both sorted, non-overlapping).
fn subtract_ranges(a: &[(u32, u32)], b: &[(u32, u32)]) -> Vec<(u32, u32)> {
    let mut out = Vec::new();
    let mut j = 0;
    for &(s, e) in a {
        let mut cur = s;
        while j < b.len() && b[j].1 < cur {
            j += 1;
        }
        let mut k = j;
        let mut alive = true;
        while k < b.len() && b[k].0 <= e {
            if b[k].0 > cur {
                out.push((cur, b[k].0 - 1));
            }
            if b[k].1 >= e {
                alive = false;
                break;
            }
            cur = b[k].1 + 1;
            k += 1;
        }
        if alive && cur <= e {
            out.push((cur, e));
        }
    }
    out
}

// ---------------------------------------------------------------------------
// General category
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum GeneralCategory {
    Lu,
    Ll,
    Lt,
    Lm,
    Lo,
    Mn,
    Mc,
    Me,
    Nd,
    Nl,
    No,
    Pc,
    Pd,
    Ps,
    Pe,
    Pi,
    Pf,
    Po,
    Sm,
    Sc,
    Sk,
    So,
    Zs,
    Zl,
    Zp,
    Cc,
    Cf,
    Cs,
    Co,
    Cn,
}

const GC_ALL: [GeneralCategory; 30] = {
    use GeneralCategory::*;
    [
        Lu, Ll, Lt, Lm, Lo, Mn, Mc, Me, Nd, Nl, No, Pc, Pd, Ps, Pe, Pi, Pf, Po, Sm, Sc, Sk, So, Zs,
        Zl, Zp, Cc, Cf, Cs, Co, Cn,
    ]
};

impl GeneralCategory {
    /// Two-letter short name (e.g. "Lu").
    pub fn short_name(self) -> &'static str {
        tables::GC_ORDER[self as usize]
    }
}

/// Partition of the code space: (start, category index); sorted, first start is 0.
fn gc_table() -> &'static [(u32, u8)] {
    static T: OnceLock<Vec<(u32, u8)>> = OnceLock::new();
    T.get_or_init(|| {
        let mut r = Reader::new(tables::GC_DATA);
        let mut out = Vec::with_capacity(4200);
        let mut pos = 0u32;
        while !r.done() {
            pos += r.uv();
            let g = r.uv() as u8;
            out.push((pos, g));
        }
        out
    })
}

fn partition_lookup(t: &[(u32, u8)], c: u32) -> u8 {
    let idx = t.partition_point(|&(s, _)| s <= c);
    t[idx - 1].1
}

pub fn general_category(c: u32) -> GeneralCategory {
    if c > 0x10FFFF {
        return GeneralCategory::Cn;
    }
    GC_ALL[partition_lookup(gc_table(), c) as usize]
}

/// Ranges of a partition table whose value satisfies `pred`.
fn partition_ranges(t: &[(u32, u8)], pred: impl Fn(u8) -> bool) -> Vec<(u32, u32)> {
    let mut out: Vec<(u32, u32)> = Vec::new();
    for (i, &(s, v)) in t.iter().enumerate() {
        if !pred(v) {
            continue;
        }
        let e = if i + 1 < t.len() { t[i + 1].0 - 1 } else { 0x10FFFF };
        if let Some(last) = out.last_mut() {
            if last.1 + 1 == s {
                last.1 = e;
                continue;
            }
        }
        out.push((s, e));
    }
    out
}

fn gc_mask(name: &str) -> Option<u32> {
    tables::GC_NAMES
        .binary_search_by(|&(n, _)| n.cmp(name))
        .ok()
        .map(|i| tables::GC_NAMES[i].1)
}

fn gc_ranges(mask: u32) -> Vec<(u32, u32)> {
    partition_ranges(gc_table(), |g| mask & (1 << g) != 0)
}

// ---------------------------------------------------------------------------
// Scripts
// ---------------------------------------------------------------------------

fn sc_table() -> &'static [(u32, u8)] {
    static T: OnceLock<Vec<(u32, u8)>> = OnceLock::new();
    T.get_or_init(|| {
        let mut r = Reader::new(tables::SC_DATA);
        let mut out = Vec::with_capacity(1800);
        let mut pos = 0u32;
        while !r.done() {
            pos += r.uv();
            let g = r.uv() as u8;
            out.push((pos, g));
        }
        out
    })
}

struct ScxData {
    /// (start, end, set index), sorted
    runs: Vec<(u32, u32, u16)>,
    sets: Vec<Vec<u8>>,
}

fn scx_data() -> &'static ScxData {
    static T: OnceLock<ScxData> = OnceLock::new();
    T.get_or_init(|| {
        let mut sets = Vec::new();
        let mut r = Reader::new(tables::SCX_SETS);
        while !r.done() {
            let n = r.uv();
            sets.push((0..n).map(|_| r.uv() as u8).collect::<Vec<u8>>());
        }
        let mut runs = Vec::new();
        let mut r = Reader::new(tables::SCX_RUNS);
        let mut next = 0u32;
        while !r.done() {
            let s = next + r.uv();
            let e = s + r.uv();
            let k = r.uv() as u16;
            runs.push((s, e, k));
            next = e + 1;
        }
        ScxData { runs, sets }
    })
}

fn script_id(name: &str) -> Option<u8> {
    tables::SCRIPT_NAMES
        .binary_search_by(|&(n, _)| n.cmp(name))
        .ok()
        .map(|i| tables::SCRIPT_NAMES[i].1)
}

/// Script property value (long name) of a code point, e.g. "Latin", "Common", "Unknown".
pub fn script(c: u32) -> &'static str {
    if c > 0x10FFFF {
        return "Unknown";
    }
    tables::SCRIPT_LONG[partition_lookup(sc_table(), c) as usize]
}

/// Script_Extensions of a code point (long names).
pub fn script_extensions(c: u32) -> Vec<&'static str> {
    let d = scx_data();
    let idx = d.runs.partition_point(|&(s, _, _)| s <= c);
    if idx > 0 && c <= d.runs[idx - 1].1 {
        return d.sets[d.runs[idx - 1].2 as usize]
            .iter()
            .map(|&i| tables::SCRIPT_LONG[i as usize])
            .collect();
    }
    vec![script(c)]
}

fn script_ranges(id: u8) -> Vec<(u32, u32)> {
    partition_ranges(sc_table(), |s| s == id)
}

fn scx_ranges(id: u8) -> Vec<(u32, u32)> {
    let d = scx_data();
    let base = script_ranges(id);
    let all_runs: Vec<(u32, u32)> = normalize_ranges(d.runs.iter().map(|&(s, e, _)| (s, e)).collect());
    let mut v = subtract_ranges(&base, &all_runs);
    for &(s, e, k) in &d.runs {
        if d.sets[k as usize].contains(&id) {
            v.push((s, e));
        }
    }
    normalize_ranges(v)
}

// ---------------------------------------------------------------------------
// Binary properties
// ---------------------------------------------------------------------------

fn binary_tables() -> &'static Vec<OnceLock<Vec<(u32, u32)>>> {
    static T: OnceLock<Vec<OnceLock<Vec<(u32, u32)>>>> = OnceLock::new();
    T.get_or_init(|| (0..tables::BINARY_PROPS.len()).map(|_| OnceLock::new()).collect())
}

/// Decoded (cached) ranges of a stored binary property, by canonical name.
fn stored_binary(canonical: &str) -> Option<&'static [(u32, u32)]> {
    let idx = tables::BINARY_PROPS.iter().position(|&(n, _)| n == canonical)?;
    let cell = &binary_tables()[idx];
    Some(cell.get_or_init(|| decode_ranges(tables::BINARY_PROPS[idx].1)).as_slice())
}

fn binary_canonical(name: &str) -> Option<&'static str> {
    tables::BINARY_NAMES
        .binary_search_by(|&(n, _)| n.cmp(name))
        .ok()
        .map(|i| tables::BINARY_NAMES[i].1)
}

fn binary_ranges(name: &str) -> Option<Vec<(u32, u32)>> {
    let canonical = binary_canonical(name)?;
    match canonical {
        "Any" => Some(vec![(0, 0x10FFFF)]),
        "ASCII" => Some(vec![(0, 0x7F)]),
        "Assigned" => Some(gc_ranges(!(1u32 << GeneralCategory::Cn as u32) & ((1 << 30) - 1))),
        _ => stored_binary(canonical).map(|r| r.to_vec()),
    }
}

/// Fast membership test for a stored binary property (canonical name).
fn has_binary(canonical: &'static str, c: u32) -> bool {
    match stored_binary(canonical) {
        Some(r) => in_ranges(r, c),
        None => false,
    }
}

/// `\p{name}` / `\p{name=value}` character properties, names exactly as written in the pattern
/// (case-sensitive, ECMA-262 names and aliases as accepted by the original). Returns sorted,
/// non-overlapping, non-adjacent inclusive ranges, or None if the original rejects the property.
/// Properties of strings are excluded (see `string_property`).
pub fn property_ranges(name: &str, value: Option<&str>) -> Option<Vec<(u32, u32)>> {
    match value {
        None => {
            if let Some(m) = gc_mask(name) {
                return Some(gc_ranges(m));
            }
            binary_ranges(name)
        }
        Some(v) => match name {
            "General_Category" | "gc" => gc_mask(v).map(gc_ranges),
            "Script" | "sc" => script_id(v).map(script_ranges),
            "Script_Extensions" | "scx" => script_id(v).map(scx_ranges),
            _ => None,
        },
    }
}

/// Membership test for the same names as `property_ranges` (slower than caching the ranges).
pub fn has_property(name: &str, value: Option<&str>, c: u32) -> Option<bool> {
    property_ranges(name, value).map(|r| in_ranges(&r, c))
}

pub fn is_id_start(c: u32) -> bool {
    if c < 0x80 {
        return (c as u8).is_ascii_alphabetic();
    }
    static T: OnceLock<&'static [(u32, u32)]> = OnceLock::new();
    in_ranges(T.get_or_init(|| stored_binary("ID_Start").unwrap()), c)
}

pub fn is_id_continue(c: u32) -> bool {
    if c < 0x80 {
        return (c as u8).is_ascii_alphanumeric() || c == b'_' as u32;
    }
    static T: OnceLock<&'static [(u32, u32)]> = OnceLock::new();
    in_ranges(T.get_or_init(|| stored_binary("ID_Continue").unwrap()), c)
}

/// ID_Start plus '$' and '_' (ECMAScript IdentifierStartChar).
pub fn is_js_id_start(c: u32) -> bool {
    c == '$' as u32 || c == '_' as u32 || is_id_start(c)
}

/// ID_Continue plus '$', ZWNJ and ZWJ (ECMAScript IdentifierPartChar).
pub fn is_js_id_continue(c: u32) -> bool {
    c == '$' as u32 || c == 0x200C || c == 0x200D || is_id_continue(c)
}

/// ECMAScript WhiteSpace: TAB VT FF SP NBSP ZWNBSP and General_Category=Zs.
pub fn is_js_whitespace(c: u32) -> bool {
    match c {
        0x09 | 0x0B | 0x0C | 0x20 | 0xA0 | 0xFEFF => true,
        _ if c < 0x1680 => false,
        _ => tables::ZS.iter().any(|&(a, b)| a <= c && c <= b),
    }
}

/// ECMAScript LineTerminator: LF CR LS PS.
pub fn is_line_terminator(c: u32) -> bool {
    matches!(c, 0x0A | 0x0D | 0x2028 | 0x2029)
}

/// Unicode `Cased` property.
pub fn is_cased(c: u32) -> bool {
    if c < 0x80 {
        return (c as u8).is_ascii_alphabetic();
    }
    static T: OnceLock<&'static [(u32, u32)]> = OnceLock::new();
    in_ranges(T.get_or_init(|| stored_binary("Cased").unwrap()), c)
}

/// Unicode `Case_Ignorable` property.
pub fn is_case_ignorable(c: u32) -> bool {
    static T: OnceLock<&'static [(u32, u32)]> = OnceLock::new();
    in_ranges(T.get_or_init(|| stored_binary("Case_Ignorable").unwrap()), c)
}

// ---------------------------------------------------------------------------
// Properties of strings (v-mode)
// ---------------------------------------------------------------------------

type StringProp = (Vec<(u32, u32)>, Vec<Vec<u32>>);

fn string_props() -> &'static Vec<StringProp> {
    static T: OnceLock<Vec<StringProp>> = OnceLock::new();
    T.get_or_init(|| {
        let mut dict = Vec::new();
        for (a, b) in decode_ranges(tables::STR_DICT) {
            dict.extend(a..=b);
        }
        tables::STRING_PROPS
            .iter()
            .map(|&(_, singles, strings)| {
                let ranges = decode_ranges(singles);
                let mut r = Reader::new(strings);
                let mut v = Vec::new();
                if !r.done() {
                    let n = r.uv();
                    for _ in 0..n {
                        let len = r.uv();
                        v.push((0..len).map(|_| dict[r.uv() as usize]).collect::<Vec<u32>>());
                    }
                }
                (ranges, v)
            })
            .collect()
    })
}

/// v-mode properties of strings (Basic_Emoji, Emoji_Keycap_Sequence, RGI_Emoji_Modifier_Sequence,
/// RGI_Emoji_Flag_Sequence, RGI_Emoji_Tag_Sequence, RGI_Emoji_ZWJ_Sequence, RGI_Emoji):
/// (single code points as merged ranges, strings of >= 2 code points, sorted); None otherwise.
pub fn string_property(name: &str) -> Option<(Vec<(u32, u32)>, Vec<Vec<u32>>)> {
    let idx = tables::STRING_PROPS.iter().position(|&(n, _, _)| n == name)?;
    Some(string_props()[idx].clone())
}

// ---------------------------------------------------------------------------
// Case folding / canonicalization for regular expressions
// ---------------------------------------------------------------------------

fn decode_pairs(s: &str) -> Vec<(u32, u32)> {
    let mut r = Reader::new(s);
    let mut out = Vec::new();
    let mut c = 0u32;
    while !r.done() {
        c += r.uv();
        let d = r.sv();
        out.push((c, (c as i64 + d) as u32));
    }
    out
}

/// Every (c, scf(c)) with scf(c) != c, sorted by c.
pub fn simple_case_fold_table() -> &'static [(u32, u32)] {
    static T: OnceLock<Vec<(u32, u32)>> = OnceLock::new();
    T.get_or_init(|| decode_pairs(tables::SCF_DATA)).as_slice()
}

/// Every (c, legacy_canonicalize(c)) with a different value, sorted by c.
pub fn legacy_canonicalize_table() -> &'static [(u32, u32)] {
    static T: OnceLock<Vec<(u32, u32)>> = OnceLock::new();
    T.get_or_init(|| decode_pairs(tables::LEGACY_DATA)).as_slice()
}

fn pair_lookup(t: &[(u32, u32)], c: u32) -> u32 {
    match t.binary_search_by(|&(k, _)| k.cmp(&c)) {
        Ok(i) => t[i].1,
        Err(_) => c,
    }
}

/// Simple case folding (CaseFolding.txt status C+S) = Canonicalize for u/v-mode /i.
pub fn simple_case_fold(c: u32) -> u32 {
    if c < 0x80 {
        return if (b'A' as u32..=b'Z' as u32).contains(&c) { c + 32 } else { c };
    }
    pair_lookup(simple_case_fold_table(), c)
}

/// Non-unicode /i Canonicalize of a code unit: u = full toUppercase(ch); if u is not a single
/// code unit return ch; if ch >= 128 && u < 128 return ch; else u. For c > 0xFFFF returns c.
pub fn legacy_canonicalize(c: u32) -> u32 {
    if c < 0x80 {
        return if (b'a' as u32..=b'z' as u32).contains(&c) { c - 32 } else { c };
    }
    if c > 0xFFFF {
        return c;
    }
    pair_lookup(legacy_canonicalize_table(), c)
}

fn build_classes(t: &[(u32, u32)]) -> Vec<(u32, u32, u32)> {
    // returns sorted (member, class_start, class_len) into a flat member pool, via a map
    let _ = t;
    Vec::new()
}

struct Classes {
    /// (code point, offset into pool, len) sorted by code point; only for non-trivial classes
    index: Vec<(u32, u32, u8)>,
    pool: Vec<u32>,
}

fn make_classes(t: &[(u32, u32)]) -> Classes {
    use std::collections::BTreeMap;
    let mut groups: BTreeMap<u32, Vec<u32>> = BTreeMap::new();
    for &(c, f) in t {
        groups.entry(f).or_default().push(c);
    }
    let mut pool = Vec::new();
    let mut index = Vec::new();
    for (rep, mut members) in groups {
        members.push(rep);
        members.sort_unstable();
        members.dedup();
        let off = pool.len() as u32;
        let len = members.len() as u8;
        for &m in &members {
            index.push((m, off, len));
        }
        pool.extend(members);
    }
    index.sort_unstable();
    Classes { index, pool }
}

fn class_lookup(cl: &'static Classes, c: u32) -> Option<&'static [u32]> {
    let i = cl.index.binary_search_by(|&(k, _, _)| k.cmp(&c)).ok()?;
    let (_, off, len) = cl.index[i];
    Some(&cl.pool[off as usize..off as usize + len as usize])
}

/// All code points with the same simple case folding as `c` (sorted, including `c`), or None
/// if `c` is alone in its class.
pub fn simple_case_fold_class(c: u32) -> Option<&'static [u32]> {
    static T: OnceLock<Classes> = OnceLock::new();
    class_lookup(T.get_or_init(|| make_classes(simple_case_fold_table())), c)
}

/// All code units with the same legacy canonicalization as `c` (sorted, including `c`), or None
/// if `c` is alone in its class.
pub fn legacy_canonicalize_class(c: u32) -> Option<&'static [u32]> {
    static T: OnceLock<Classes> = OnceLock::new();
    class_lookup(T.get_or_init(|| make_classes(legacy_canonicalize_table())), c)
}

// ---------------------------------------------------------------------------
// Case mapping
// ---------------------------------------------------------------------------

/// Result of a full case mapping: up to 3 code points. Iterates over them.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CaseMapping {
    buf: [u32; 3],
    len: u8,
    pos: u8,
}

impl CaseMapping {
    fn one(c: u32) -> Self {
        CaseMapping { buf: [c, 0, 0], len: 1, pos: 0 }
    }
    fn from_iter(it: impl Iterator<Item = char>) -> Self {
        let mut m = CaseMapping { buf: [0; 3], len: 0, pos: 0 };
        for ch in it {
            m.buf[m.len as usize] = ch as u32;
            m.len += 1;
        }
        m
    }
    /// The mapped code points.
    pub fn as_slice(&self) -> &[u32] {
        &self.buf[self.pos as usize..self.len as usize]
    }
    /// True if the mapping is the single code point `c`.
    pub fn is_identity(&self, c: u32) -> bool {
        self.len == 1 && self.buf[0] == c
    }
}

impl Iterator for CaseMapping {
    type Item = u32;
    fn next(&mut self) -> Option<u32> {
        if self.pos < self.len {
            self.pos += 1;
            Some(self.buf[self.pos as usize - 1])
        } else {
            None
        }
    }
    fn size_hint(&self) -> (usize, Option<usize>) {
        let n = (self.len - self.pos) as usize;
        (n, Some(n))
    }
}

impl ExactSizeIterator for CaseMapping {}

/// Full (unconditional, language-independent) uppercase mapping of a code point.
pub fn to_upper_full(c: u32) -> CaseMapping {
    match char::from_u32(c) {
        Some(ch) if ch.is_ascii() => CaseMapping::one(ch.to_ascii_uppercase() as u32),
        Some(ch) => CaseMapping::from_iter(ch.to_uppercase()),
        None => CaseMapping::one(c),
    }
}

/// Full (unconditional, language-independent) lowercase mapping of a code point
/// (U+03A3 maps to U+03C3; the final-sigma rule is applied by `str_to_lower`).
pub fn to_lower_full(c: u32) -> CaseMapping {
    match char::from_u32(c) {
        Some(ch) if ch.is_ascii() => CaseMapping::one(ch.to_ascii_lowercase() as u32),
        Some(ch) => CaseMapping::from_iter(ch.to_lowercase()),
        None => CaseMapping::one(c),
    }
}

/// Decode the code point at `i` (lone surrogates are returned as themselves); returns (cp, len).
#[inline]
fn cp_at(s: &[u16], i: usize) -> (u32, usize) {
    let u = s[i] as u32;
    if (0xD800..0xDC00).contains(&u) && i + 1 < s.len() {
        let l = s[i + 1] as u32;
        if (0xDC00..0xE000).contains(&l) {
            return (0x10000 + ((u - 0xD800) << 10) + (l - 0xDC00), 2);
        }
    }
    (u, 1)
}

/// Decode the code point ending just before `i`; returns (cp, len).
#[inline]
fn cp_before(s: &[u16], i: usize) -> (u32, usize) {
    let u = s[i - 1] as u32;
    if (0xDC00..0xE000).contains(&u) && i >= 2 {
        let h = s[i - 2] as u32;
        if (0xD800..0xDC00).contains(&h) {
            return (0x10000 + ((h - 0xD800) << 10) + (u - 0xDC00), 2);
        }
    }
    (u, 1)
}

#[inline]
fn push_cp(out: &mut Vec<u16>, c: u32) {
    if c < 0x10000 {
        out.push(c as u16);
    } else {
        let c = c - 0x10000;
        out.push((0xD800 + (c >> 10)) as u16);
        out.push((0xDC00 + (c & 0x3FF)) as u16);
    }
}

/// String.prototype.toUpperCase (lone surrogates unchanged).
pub fn str_to_upper(s: &[u16]) -> Vec<u16> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        let u = s[i];
        if u < 0x80 {
            out.push((u as u8).to_ascii_uppercase() as u16);
            i += 1;
            continue;
        }
        let (c, n) = cp_at(s, i);
        for m in to_upper_full(c) {
            push_cp(&mut out, m);
        }
        i += n;
    }
    out
}

/// Final_Sigma condition for the capital sigma at code unit index `i` (ICU semantics).
fn is_final_sigma(s: &[u16], i: usize) -> bool {
    // preceded by a cased letter, skipping case-ignorable characters
    let mut j = i;
    let mut before = false;
    while j > 0 {
        let (c, n) = cp_before(s, j);
        j -= n;
        if is_case_ignorable(c) {
            continue;
        }
        before = is_cased(c);
        break;
    }
    if !before {
        return false;
    }
    // not followed by a cased letter, skipping case-ignorable characters
    let mut j = i + 1;
    while j < s.len() {
        let (c, n) = cp_at(s, j);
        j += n;
        if is_case_ignorable(c) {
            continue;
        }
        return !is_cased(c);
    }
    true
}

/// String.prototype.toLowerCase incl. the final sigma rule (lone surrogates unchanged).
pub fn str_to_lower(s: &[u16]) -> Vec<u16> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        let u = s[i];
        if u < 0x80 {
            out.push((u as u8).to_ascii_lowercase() as u16);
            i += 1;
            continue;
        }
        if u == 0x3A3 {
            out.push(if is_final_sigma(s, i) { 0x3C2 } else { 0x3C3 });
            i += 1;
            continue;
        }
        let (c, n) = cp_at(s, i);
        for m in to_lower_full(c) {
            push_cp(&mut out, m);
        }
        i += n;
    }
    out
}

// ---------------------------------------------------------------------------
// Normalization
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NormForm {
    Nfc,
    Nfd,
    Nfkc,
    Nfkd,
}

struct NormData {
    /// (start, end, ccc)
    ccc: Vec<(u32, u32, u8)>,
    /// (code point, offset, len) into `pool`, sorted; canonical single-level mappings
    canon: Vec<(u32, u32, u8)>,
    /// same for compatibility mappings
    compat: Vec<(u32, u32, u8)>,
    pool: Vec<u32>,
    /// ((first << 21) | second, composite), sorted
    compose: Vec<(u64, u32)>,
}

fn norm_data() -> &'static NormData {
    static T: OnceLock<NormData> = OnceLock::new();
    T.get_or_init(|| {
        let mut ccc = Vec::new();
        let mut r = Reader::new(tables::CCC_DATA);
        let mut next = 0u32;
        while !r.done() {
            let s = next + r.uv();
            let e = s + r.uv();
            let v = r.uv() as u8;
            ccc.push((s, e, v));
            next = e + 1;
        }
        let mut pool = Vec::new();
        let mut canon = Vec::new();
        let mut compose = Vec::new();
        let mut r = Reader::new(tables::CANON_DATA);
        let mut c = 0u32;
        while !r.done() {
            c += r.uv();
            let lf = r.uv();
            let len = lf >> 1;
            let off = pool.len() as u32;
            let mut p = c as i64;
            for _ in 0..len {
                p += r.sv();
                pool.push(p as u32);
            }
            if lf & 1 != 0 {
                compose.push((((pool[off as usize] as u64) << 21) | pool[off as usize + 1] as u64, c));
            }
            canon.push((c, off, len as u8));
        }
        let mut compat = Vec::new();
        let mut r = Reader::new(tables::COMPAT_DATA);
        let mut c = 0u32;
        while !r.done() {
            c += r.uv();
            let len = r.uv();
            let off = pool.len() as u32;
            let mut p = c as i64;
            for _ in 0..len {
                p += r.sv();
                pool.push(p as u32);
            }
            compat.push((c, off, len as u8));
        }
        compose.sort_unstable();
        NormData { ccc, canon, compat, pool, compose }
    })
}

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

/// Canonical combining class (as implemented by the original).
pub fn canonical_combining_class(c: u32) -> u8 {
    if c < 0x300 {
        return 0;
    }
    let t = &norm_data().ccc;
    let idx = t.partition_point(|&(s, _, _)| s <= c);
    if idx > 0 && c <= t[idx - 1].1 {
        t[idx - 1].2
    } else {
        0
    }
}

fn mapping(t: &[(u32, u32, u8)], pool: &'static [u32], c: u32) -> Option<&'static [u32]> {
    let i = t.binary_search_by(|&(k, _, _)| k.cmp(&c)).ok()?;
    let (_, off, len) = t[i];
    Some(&pool[off as usize..off as usize + len as usize])
}

fn decompose_into(c: u32, compat: bool, out: &mut Vec<u32>) {
    if (S_BASE..S_BASE + S_COUNT).contains(&c) {
        let s = c - S_BASE;
        out.push(L_BASE + s / N_COUNT);
        out.push(V_BASE + (s % N_COUNT) / T_COUNT);
        let t = s % T_COUNT;
        if t != 0 {
            out.push(T_BASE + t);
        }
        return;
    }
    if c < 0xA0 {
        out.push(c);
        return;
    }
    let d = norm_data();
    if let Some(m) = mapping(&d.canon, &d.pool, c) {
        for &x in m {
            decompose_into(x, compat, out);
        }
        return;
    }
    if compat {
        if let Some(m) = mapping(&d.compat, &d.pool, c) {
            for &x in m {
                decompose_into(x, compat, out);
            }
            return;
        }
    }
    out.push(c);
}

fn compose_pair(a: u32, b: u32) -> Option<u32> {
    // Hangul
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a)
        && (a - S_BASE) % T_COUNT == 0
        && (T_BASE + 1..T_BASE + T_COUNT).contains(&b)
    {
        return Some(a + (b - T_BASE));
    }
    let key = ((a as u64) << 21) | b as u64;
    let t = &norm_data().compose;
    t.binary_search_by(|&(k, _)| k.cmp(&key)).ok().map(|i| t[i].1)
}

/// String.prototype.normalize (lone surrogates pass through unchanged).
pub fn normalize(s: &[u16], form: NormForm) -> Vec<u16> {
    // quick checks: code units below these limits are unaffected by the respective forms
    let limit = match form {
        NormForm::Nfc => 0x300,
        NormForm::Nfd => 0xC0,
        NormForm::Nfkc | NormForm::Nfkd => 0xA0,
    };
    if s.iter().all(|&u| (u as u32) < limit) {
        return s.to_vec();
    }
    let compat = matches!(form, NormForm::Nfkc | NormForm::Nfkd);
    // decompose
    let mut cps: Vec<u32> = Vec::with_capacity(s.len() + 8);
    let mut i = 0;
    while i < s.len() {
        let (c, n) = cp_at(s, i);
        i += n;
        if (0xD800..0xE000).contains(&c) {
            cps.push(c);
        } else {
            decompose_into(c, compat, &mut cps);
        }
    }
    // canonical ordering: stable sort of each run of non-starters by ccc
    let classes: Vec<u8> = cps.iter().map(|&c| canonical_combining_class(c)).collect();
    let mut k = 0;
    while k < cps.len() {
        if classes[k] == 0 {
            k += 1;
            continue;
        }
        let start = k;
        while k < cps.len() && classes[k] != 0 {
            k += 1;
        }
        if k - start > 1 {
            let mut run: Vec<(u8, u32)> = (start..k).map(|j| (classes[j], cps[j])).collect();
            run.sort_by_key(|&(cc, _)| cc); // stable
            for (j, (_, c)) in run.into_iter().enumerate() {
                cps[start + j] = c;
            }
        }
    }
    if matches!(form, NormForm::Nfc | NormForm::Nfkc) {
        cps = compose(&cps);
    }
    let mut out = Vec::with_capacity(cps.len());
    for c in cps {
        push_cp(&mut out, c);
    }
    out
}

fn compose(cps: &[u32]) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::with_capacity(cps.len());
    let mut starter: Option<usize> = None;
    let mut last_cc: u8 = 0;
    for &c in cps {
        let cc = canonical_combining_class(c);
        if let Some(sp) = starter {
            let adjacent = out.len() == sp + 1;
            if adjacent || (last_cc != 0 && last_cc < cc) {
                if let Some(comp) = compose_pair(out[sp], c) {
                    out[sp] = comp;
                    continue;
                }
            }
        }
        if cc == 0 {
            starter = Some(out.len());
        }
        last_cc = cc;
        out.push(c);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn u(s: &str) -> Vec<u16> {
        s.encode_utf16().collect()
    }

    #[test]
    fn categories() {
        assert_eq!(general_category('A' as u32), GeneralCategory::Lu);
        assert_eq!(general_category('a' as u32), GeneralCategory::Ll);
        assert_eq!(general_category(0x10FFFF), GeneralCategory::Cn);
        assert_eq!(general_category(0xD800), GeneralCategory::Cs);
        assert_eq!(general_category(0x10D4A), GeneralCategory::Lo); // Garay (16.0)
        assert_eq!(script(0x41), "Latin");
        assert_eq!(script(0x10940), "Sidetic"); // 17.0
        assert!(script_extensions(0x0300).len() > 3);
    }

    #[test]
    fn properties() {
        assert_eq!(property_ranges("ASCII", None), Some(vec![(0, 0x7F)]));
        assert!(property_ranges("WSpace", None).is_none());
        assert!(property_ranges("space", None).is_some());
        assert!(property_ranges("Script", Some("Hrkt")).is_none());
        assert!(property_ranges("Latin", None).is_none());
        assert!(property_ranges("lu", None).is_none());
        let l = property_ranges("L", None).unwrap();
        assert_eq!(l[0], (0x41, 0x5A));
        let lc = property_ranges("gc", Some("Cased_Letter")).unwrap();
        assert_eq!(lc[0], (0x41, 0x5A));
        let g = property_ranges("scx", Some("Grek")).unwrap();
        assert!(in_ranges(&g, 0x0342) && in_ranges(&g, 0x3B1));
        assert!(is_id_start('a' as u32) && !is_id_start('1' as u32) && is_id_continue('1' as u32));
        assert!(is_js_id_start('$' as u32) && is_js_id_continue(0x200D));
        assert!(is_js_whitespace(0x3000) && is_js_whitespace(0xFEFF) && !is_js_whitespace(0x200B));
        assert!(is_line_terminator(0x2028) && !is_line_terminator(0x85));
        let (singles, strings) = string_property("RGI_Emoji_Flag_Sequence").unwrap();
        assert!(singles.is_empty() && strings.len() >= 259);
        assert!(string_property("Emoji").is_none());
    }

    #[test]
    fn folding() {
        assert_eq!(simple_case_fold('K' as u32), 'k' as u32);
        assert_eq!(simple_case_fold(0x212A), 'k' as u32);
        assert_eq!(simple_case_fold(0x1E9E), 0xDF);
        assert_eq!(simple_case_fold(0x130), 0x130);
        assert_eq!(simple_case_fold(0x3C2), 0x3C3);
        assert_eq!(simple_case_fold(0x1FD3), 0x390);
        assert_eq!(simple_case_fold_class('s' as u32), Some(&['S' as u32, 's' as u32, 0x17F][..]));
        assert_eq!(legacy_canonicalize('a' as u32), 'A' as u32);
        assert_eq!(legacy_canonicalize(0x17F), 0x17F);
        assert_eq!(legacy_canonicalize(0xDF), 0xDF);
        assert_eq!(legacy_canonicalize(0xB5), 0x39C);
        assert_eq!(legacy_canonicalize(0x10428), 0x10428);
    }

    #[test]
    fn casing() {
        assert_eq!(str_to_upper(&u("straße")), u("STRASSE"));
        assert_eq!(str_to_lower(&u("ΑΣ")), u("ας"));
        assert_eq!(str_to_lower(&u("ΑΣΑ")), u("ασα"));
        assert_eq!(str_to_lower(&u("ʰΣ")), u("ʰσ"));
