use std::io::{BufRead, Write};
use ucore::*;

fn json_ranges(r: &Option<Vec<(u32, u32)>>) -> String {
    match r {
        None => "null".to_string(),
        Some(v) => format!("[{}]", v.iter().map(|(a, b)| format!("[{},{}]", a, b)).collect::<Vec<_>>().join(",")),
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    match args[1].as_str() {
        // read JSON array of [name, value|null] pairs (one per line, simple format "name\tvalue")
        "props" => {
            let stdin = std::io::stdin();
            for line in stdin.lock().lines() {
                let line = line.unwrap();
                let mut it = line.splitn(2, '\t');
                let n = it.next().unwrap().to_string();
                let v = it.next().map(|s| s.to_string());
                let v = v.filter(|s| s != "\u{1}");
                let r = property_ranges(&n, v.as_deref());
                writeln!(out, "{}", json_ranges(&r)).unwrap();
            }
        }
        "case" => {
            // per code point: upper and lower of the single code point string, if different
            for c in 0u32..0x110000 {
                let s: Vec<u16> = if c < 0x10000 { vec![c as u16] } else { let d = c - 0x10000; vec![(0xD800 + (d >> 10)) as u16, (0xDC00 + (d & 0x3FF)) as u16] };
                let up = str_to_upper(&s);
                let lo = str_to_lower(&s);
                if up != s || lo != s {
                    writeln!(out, "{} {:?} {:?}", c, up, lo).unwrap();
                }
            }
        }
        "norm" => {
            for c in 0u32..0x110000 {
                if (0xD800..0xE000).contains(&c) { continue; }
                let s: Vec<u16> = if c < 0x10000 { vec![c as u16] } else { let d = c - 0x10000; vec![(0xD800 + (d >> 10)) as u16, (0xDC00 + (d & 0x3FF)) as u16] };
                let f = [NormForm::Nfd, NormForm::Nfkd, NormForm::Nfc, NormForm::Nfkc].map(|f| normalize(&s, f));
                if f.iter().any(|x| *x != s) {
                    writeln!(out, "{} {:?} {:?} {:?} {:?}", c, f[0], f[1], f[2], f[3]).unwrap();
                }
            }
        }
        "strings" => {
            // lines of hex code units separated by spaces -> output normalized/cased variants
            let stdin = std::io::stdin();
            for line in stdin.lock().lines() {
                let line = line.unwrap();
                let s: Vec<u16> = line.split_whitespace().map(|x| u16::from_str_radix(x, 16).unwrap()).collect();
                let hex = |v: &Vec<u16>| v.iter().map(|x| format!("{:04x}", x)).collect::<Vec<_>>().join(" ");
                writeln!(out, "{}|{}|{}|{}|{}|{}", hex(&str_to_upper(&s)), hex(&str_to_lower(&s)),
                    hex(&normalize(&s, NormForm::Nfc)), hex(&normalize(&s, NormForm::Nfd)), hex(&normalize(&s, NormForm::Nfkc)), hex(&normalize(&s, NormForm::Nfkd))).unwrap();
            }
        }
        "fold" => {
            for &(c, f) in simple_case_fold_table() { writeln!(out, "U {} {}", c, f).unwrap(); }
            for &(c, f) in legacy_canonicalize_table() { writeln!(out, "L {} {}", c, f).unwrap(); }
        }
        "strprops" => {
            for n in ["Basic_Emoji", "Emoji_Keycap_Sequence", "RGI_Emoji_Modifier_Sequence", "RGI_Emoji_Flag_Sequence", "RGI_Emoji_Tag_Sequence", "RGI_Emoji_ZWJ_Sequence", "RGI_Emoji"] {
                let (r, s) = string_property(n).unwrap();
                writeln!(out, "{} {} {}", n, json_ranges(&Some(r)), s.iter().map(|x| x.iter().map(|c| format!("{:X}", c)).collect::<Vec<_>>().join(".")).collect::<Vec<_>>().join(",")).unwrap();
            }
        }
        _ => panic!("unknown mode"),
    }
}
